<?php require '/etc/cei-labs/natas-runtime/natas33.php'; $name = isset($_POST['name']) && is_string($_POST['name']) ? $_POST['name'] : ''; $metadata = isset($_POST['metadata']) && is_string($_POST['metadata']) ? $_POST['metadata'] : ''; $ok = strlen($name) <= 24 && strlen($metadata) <= 24 && $name === 'field-report.txt' && $metadata === 'archive:reviewed'; if ($ok) { $registry = '/var/lib/cei-labs/natas-batch-d/uploads-' . $natas_team . '.json'; $record = array('team' => $natas_team, 'artifacts' => array(array('name' => $name, 'metadata' => $metadata))); file_put_contents($registry, json_encode($record), LOCK_EX); } ?><!doctype html><html><body><h1>Inert upload registry</h1><p>The registry stores no file bytes and records only a benign metadata lifecycle event.</p><form method="post"><input name="name" maxlength="24"><input name="metadata" maxlength="24"><button>Record</button></form><?php if ($ok): ?><p>Metadata handoff: <?php echo htmlspecialchars($natas34_secret, ENT_QUOTES, 'UTF-8'); ?></p><?php else: ?><p>No reviewed artifact.</p><?php endif; ?></body></html>
